/// <reference types="vite/client" />

declare module "*.vue" {
  import type { DefineComponent } from "vue";
  const component: DefineComponent<object, object, unknown>;
  export default component;
}

/** Injected by Vite's `define`; the version in src-tauri/tauri.conf.json. */
declare const __APP_VERSION__: string;
/** ISO timestamp of the frontend build. */
declare const __APP_BUILD_DATE__: string;
/** Full git commit hash of the build, or "" when unknown. */
declare const __APP_COMMIT__: string;
/** Release notes (Markdown) generated by the release workflow, or "". */
declare const __APP_RELEASE_NOTES__: string;
